(window._lmI18nQueue = window._lmI18nQueue || []).push(["pl", "site-help-glossary", {
"site.help.glossary.playNow": "Graj teraz",
"site.help.glossary.helpCenter": "Centrum pomocy",
"site.help.glossary.strategyGuide": "Poradnik strategii",
"site.help.glossary.unblocked": "🔓 Bez blokady",
"site.help.glossary.glossary": "Słowniczek",
"site.help.glossary.ioGamesGlossary": "Słowniczek gier IO",
"site.help.glossary.termsEveryIoGame": "Ponad 40 pojęć, które powinien znać każdy gracz gier IO. Od podstawowego sterowania po zaawansowane techniki: kompletny słownik do Agar.io, Slither.io, Expanding Land i wszystkich gier z komórkami.",
"site.help.glossary.jumpToCategory": "Przejdź do kategorii",
"site.help.glossary.basics": "🎮 Podstawy",
"site.help.glossary.controls": "⌨️ Sterowanie",
"site.help.glossary.mechanics": "⚙️ Mechanika",
"site.help.glossary.techniques": "🎯 Techniki",
"site.help.glossary.strategy": "🧠 Strategia",
"site.help.glossary.community": "👥 Społeczność",
"site.help.glossary.expandingLand": "🌍 Expanding Land",
"site.help.glossary.searchTermsEG": "🔍 Szukaj pojęć... (np. 'split', 'wirus', 'W')",
"site.help.glossary.noTermsFoundTry": "Nie znaleziono pojęć. Spróbuj innego wyszukiwania.",
"site.help.glossary.cell": "<span class=\"emoji\">⚪</span> Komórka",
"site.help.glossary.theCircularBlobYou": "Okrągła kulka, którą sterujesz w grze. Twoja komórka rośnie, jedząc kropki jedzenia i inne, mniejsze komórki. W Agar.io i Expanding Land zaczynasz jako malutka komórka i próbujesz stać się największą na serwerze.",
"site.help.glossary.alsoCalledBlobPlayer": "Inne nazwy: blob, gracz, kulka",
"site.help.glossary.mass": "<span class=\"emoji\">⚖️</span> Masa",
"site.help.glossary.theSizeWeightOf": "Rozmiar/waga twojej komórki, pokazywana jako liczba. Większa masa = większa komórka. Masę zdobywasz, jedząc jedzenie, innych graczy lub wirusy (jeśli jesteś wystarczająco duży). Tracisz ją z czasem przez naturalny ubytek: około 0,8% co 4 sekundy według standardowych zasad Agar.io.",
"site.help.glossary.alsoCalledSizeScore": "Inne nazwy: rozmiar, wynik, waga",
"site.help.glossary.foodPellets": "<span class=\"emoji\">🟢</span> Jedzenie / kulki",
"site.help.glossary.smallColoredDotsScattered": "Małe kolorowe kropki rozrzucone po mapie. Zjedzenie ich daje trochę masy (zwykle 1 za kulkę). Ciągle pojawiają się na nowo, więc zawsze jest co jeść – szczególnie przydatne na początku gry, gdy jesteś za mały, żeby jeść innych graczy.",
"site.help.glossary.leaderboard": "<span class=\"emoji\">🏆</span> Ranking",
"site.help.glossary.theRankedListOf": "Lista najlepszych graczy według masy, widoczna w prawym górnym rogu. Wejście do rankingu robi z ciebie cel: każdy ambitny gracz zacznie na ciebie polować. W Expanding Land ranking aktualizuje się na żywo dla wszystkich 3840 graczy.",
"site.help.glossary.spawn": "<span class=\"emoji\">🔄</span> Spawn",
"site.help.glossary.theActOfEntering": "Wejście do gry nową komórką. Przy spawnie zaczynasz z niewielką masą w losowym miejscu mapy. Po śmierci możesz od razu zrobić respawn nową komórką.",
"site.help.glossary.controlsKeys": "⌨️ Sterowanie i klawisze",
"site.help.glossary.splitSpace": "<span class=\"emoji\">✂️</span> Split (Space)",
"site.help.glossary.pressSpaceToSplit": "Naciśnij <strong>Space</strong>, żeby zrobić split i podzielić komórkę na dwie połowy. Jedna połowa wystrzeliwuje do przodu z dużą prędkością – użyj tego, żeby złapać mniejszych graczy, którzy myślą, że są poza zasięgiem. Split możesz zrobić do 16 razy (16 kawałków komórki). Podzielone komórki łączą się z powrotem po upływie czasu odnowienia.",
"site.help.glossary.the2RuleYou": "💡 Zasada 2×: możesz zjeść komórkę tylko wtedy, gdy masz co najmniej 2× jej masy. Przy splicie każda połowa zachowuje swój pęd – użyj tego, żeby zaskoczyć odległe cele.",
"site.help.glossary.wEjectMass": "<span class=\"emoji\">🟡</span> W (wyrzut masy)",
"site.help.glossary.pressWToEject": "Naciśnij <strong>W</strong>, żeby wyrzucić małą kulkę masy w kierunku kursora. Zastosowania: feed dla członków drużyny, strzelanie wirusami (7 naciśnięć W = strzał wirusem), przynęty w pułapkach albo zmniejszenie się, żeby szybciej się poruszać. Każde naciśnięcie W kosztuje około 15-16 masy, ale wyrzucona kulka jest trochę mniejsza przez utratę masy.",
"site.help.glossary.alsoCalledFeedEject": "Inne nazwy: feed, eject, strzał masą",
"site.help.glossary.spectate": "<span class=\"emoji\">👁️</span> Obserwuj",
"site.help.glossary.watchTheGameWithout": "Oglądaj grę bez grania. W Expanding Land jest ponad 200 miejsc dla widzów z wolną kamerą: możesz latać po całej mapie i obserwować dowolnego gracza. Świetny sposób na naukę technik od doświadczonych graczy.",
"site.help.glossary.gameMechanics": "⚙️ Mechanika gry",
"site.help.glossary.virus": "<span class=\"emoji\">🟢</span> Wirus",
"site.help.glossary.theSpikyGreenCircles": "Kolczaste zielone koła na mapie. Jeśli jesteś większy od wirusa i go dotkniesz, <strong>rozbijasz się</strong>: twoja komórka rozpada się na wiele małych kawałków. Jeśli jesteś mniejszy, możesz schować się za wirusem albo w nim. Wirusami możesz też strzelać w przeciwników: naciśnij W 7 razy w wirusa, a nowy wirus poleci w tym kierunku.",
"site.help.glossary.virusesAreBothDefensive": "💡 Wirusy są jednocześnie tarczą obronną i bronią ofensywną. Dobrzy gracze strzelają wirusami, żeby rozbić dużych przeciwników i ukraść im masę.",
"site.help.glossary.mergeRecombine": "<span class=\"emoji\">🔗</span> Łączenie",
"site.help.glossary.afterSplittingYourCell": "Po splicie kawałki twojej komórki w końcu łączą się z powrotem w jedną. Czas łączenia zależy od twojej całkowitej masy: większe komórki łączą się dłużej. W czasie odnowienia twoje komórki nachodzą na siebie, ale się nie łączą. Gdy czas minie, sklejają się ze sobą.",
"site.help.glossary.decay": "<span class=\"emoji\">📉</span> Ubytek masy",
"site.help.glossary.allCellsLoseMass": "Wszystkie komórki z czasem tracą masę. To ubytek masy (decay), który nie pozwala żadnemu graczowi rosnąć w nieskończoność. Tempo ubytku w standardowym Agar.io i w Expanding Land to około <strong>0,8% twojej masy co 4 sekundy</strong>. Większe komórki tracą więcej w liczbach bezwzględnych: komórka o masie 10 000 traci ~80 masy na cykl, a komórka o masie 100 traci mniej niż 1.",
"site.help.glossary.ghostCells": "<span class=\"emoji\">👻</span> Komórki-duchy",
"site.help.glossary.inExpandingLandWhen": "W Expanding Land po śmierci twoje komórki na chwilę pojawiają się jako przezroczyste „komórki-duchy”, które pokazują dokładnie, gdzie cię zjedzono. Dzięki temu rozumiesz, co się stało, i uczysz się na swojej śmierci: to był split kill? Rozbicie na wirusie? Feed od członka drużyny?",
"site.help.glossary.mapArena": "<span class=\"emoji\">🗺️</span> Mapa / arena",
"site.help.glossary.thePlayingFieldWhere": "Pole gry, na którym znajdują się wszystkie komórki. W Agar.io mapa ma stały rozmiar. W Expanding Land mapa <strong>dynamicznie zmienia rozmiar</strong> od ¼× do 4× zależnie od liczby aktywnych graczy: więcej graczy to większa arena, mniej graczy to ciaśniejsza mapa, na której akcja jest gęsta.",
"site.help.glossary.advancedTechniques": "🎯 Zaawansowane techniki",
"site.help.glossary.tricksplit": "<span class=\"emoji\">🎯</span> Tricksplit",
"site.help.glossary.anAdvancedMoveWhere": "Zaawansowany ruch, w którym robisz kilka splitów szybko po sobie (podwójny albo potrójny split), żeby dosięgnąć celu, który wydaje się za daleko. Gdy robisz split już podzielonymi komórkami, każdy kawałek wystrzeliwuje z pędem i twój realny zasięg jest dużo większy niż przy jednym splicie. Wymaga precyzyjnego wyczucia czasu i ustawienia kursora.",
"site.help.glossary.doubleSplitSpaceSpace": "💡 Podwójny split: szybko Space → Space. Drugi split wylatuje z kawałka, który już jest w ruchu, i pokonuje 2× większy dystans.",
"site.help.glossary.popsplit": "<span class=\"emoji\">💥</span> Popsplit",
"site.help.glossary.aTechniqueWhereYou": "Technika, w której celowo zjadasz wirusa, żeby rozpaść się na wiele kawałków, a potem od razu robisz split, żeby zjeść pobliskiego przeciwnika. Chodzi o to, że wiele małych komórek z rozbicia plus pęd splitu pozwala połknąć przeciwnika, który myślał, że jest bezpieczny. Duże ryzyko, duża nagroda: potrzebujesz dość masy, żeby przetrwać rozbicie.",
"site.help.glossary.baitAndSwitch": "<span class=\"emoji\">🪤</span> Przynęta",
"site.help.glossary.aStrategyWhereYou": "Strategia, w której używasz małego kawałka podzielonej komórki jako przynęty. Przeciwnik goni mały kawałek i nie zauważa, że twój większy kawałek czeka, żeby zjeść go splitem, gdy tylko się rzuci. Działa najlepiej, gdy masz 2 komórki różnej wielkości.",
"site.help.glossary.cannonSelfFeed": "<span class=\"emoji\">🔫</span> Działo / self-feed",
"site.help.glossary.rapidlyPressingWTo": "Szybkie naciskanie W, żeby przelać masę z jednej swojej komórki do drugiej. Gdy masz dwie podzielone komórki, możesz dawać W z mniejszej do większej, żeby urosła na tyle, by zjeść pobliski cel. Nazywa się to też „self-feed”, bo dajesz feed sam sobie między własnymi komórkami.",
"site.help.glossary.virusShot": "<span class=\"emoji\">🚀</span> Strzał wirusem",
"site.help.glossary.pressingWIntoA": "Naciśnięcie W 7 razy w wirusa wystrzeliwuje nowego wirusa w tym kierunku. Używaj tego w ataku, żeby rozbić dużych przeciwników, albo w obronie, żeby zrobić osłonę. Każde W w wirusa kosztuje masę, więc 7 naciśnięć = łącznie około 100-110 masy. Wystrzelony wirus leci prosto, dopóki się nie zatrzyma.",
"site.help.glossary.lineSplit": "<span class=\"emoji\">➡️</span> Line split",
"site.help.glossary.splittingInAStraight": "Split w linii prostej w stronę celu, żeby odłączona komórka przeleciała jak najdalej. Gdy ustawisz kursor daleko, w jednej linii z twoją komórką i celem, kawałek dostaje maksymalną prędkość. Niezbędne do killi z dużej odległości.",
"site.help.glossary.strategyConcepts": "🧠 Strategia i pojęcia",
"site.help.glossary.teaming": "<span class=\"emoji\">🤝</span> Teaming",
"site.help.glossary.twoOrMorePlayers": "Dwóch lub więcej graczy współpracuje, żeby zdominować serwer. Członkowie drużyny dają sobie feed (W), koordynują ataki wirusami i chronią się nawzajem. Teaming budzi kontrowersje: część graczy uważa go za nieuczciwy w trybach free-for-all. Expanding Land ma <strong>system anti-teaming</strong>, który nakłada kary w postaci ubytku masy na graczy, którzy za bardzo teamują.",
"site.help.glossary.antiTeaming": "<span class=\"emoji\">⚖️</span> Anti-teaming",
"site.help.glossary.aSystemThatPenalizes": "System, który karze graczy za nadmierny teaming. W Expanding Land anti-teaming używa <strong>systemu ubytku masy z wykładniczym mnożnikiem</strong> (przeniesionego z Delta Server): każda akcja (rozbicie na wirusie, split, naciśnięcie W) zwiększa jedną wartość mnożnika. Twój rzeczywisty ubytek liczy się jako base_decay × pow(1.086, multiplier). Mnożnik sam spada z czasem dzięki stałej kompensacji, więc przy normalnej grze wracasz do normy automatycznie, bez żadnych timerów.",
"site.help.glossary.multiboxing": "<span class=\"emoji\">📱</span> Multiboxing",
"site.help.glossary.playingWithMultipleBrowser": "Granie w kilku kartach przeglądarki lub na kilku kontach jednocześnie i sterowanie kilkoma komórkami naraz. W Expanding Land multiboxing jest <strong>dozwolony, ale z zasadami</strong>: każdy gracz może używać do <strong>4 kont</strong>. Dzięki temu dobrzy gracze mogą strategicznie grać multiboxem, a gra pozostaje uczciwa.",
"site.help.glossary.bots": "<span class=\"emoji\">🤖</span> Boty",
"site.help.glossary.automatedPlayersControlledBy": "Automatyczni gracze sterowani przez program zamiast przez ludzi. W Expanding Land boty serwera i prawdziwi gracze to osobne grupy. Zobacz <a href=\"/no-bots.html\">poradnik o botach</a>.",
"site.help.glossary.cornerTrap": "<span class=\"emoji\">🧱</span> Pułapka w rogu",
"site.help.glossary.trappingAPlayerIn": "Zapędzenie gracza w róg mapy, z którego nie może uciec. Krawędź mapy blokuje ruch, więc jeśli jesteś wystarczająco duży i staniesz między przeciwnikiem a rogiem, nie ma on dokąd uciec. Jeden z najpewniejszych sposobów na kill dla doświadczonych graczy.",
"site.help.glossary.soloFfa": "<span class=\"emoji\">🎮</span> Solo / FFA",
"site.help.glossary.ffaStandsForFree": "<strong>FFA</strong> to skrót od Free-For-All (każdy na każdego). Każdy gra sam, bez przypisanych drużyn.",
"site.help.glossary.slowPlay": "<span class=\"emoji\">🐢</span> Wolna gra",
"site.help.glossary.aPatientStrategyWhere": "Cierpliwa strategia, w której nie robisz splitu, chyba że kill jest pewny. Zamiast gonić każdy cel, rośniesz na jedzeniu i czekasz, aż przeciwnicy popełnią błąd. Gracze grający wolno często żyją dłużej i stabilnie budują masę. Szczególnie skuteczne na arenach z dużą liczbą graczy, jak Expanding Land.",
"site.help.glossary.communityMods": "👥 Społeczność i mody",
"site.help.glossary.modExtension": "<span class=\"emoji\">🧩</span> Mod / rozszerzenie",
"site.help.glossary.aBrowserExtensionThat": "Rozszerzenie przeglądarki, które dodaje do gry nowe funkcje: własne skiny, minimapę, sterowanie zoomem, makra i więcej. Popularne mody do Agar.io i Expanding Land to <a href=\"https://www.legendmod.ml/\" style=\"color:#6ee7b7\">Legend Mod</a>, <a href=\"https://deltio.pages.dev/\" style=\"color:#6ee7b7\">Delta</a> i <a href=\"https://agar2.com/\" style=\"color:#6ee7b7\">Agar2</a>.",
"site.help.glossary.skin": "<span class=\"emoji\">🎨</span> Skin",
"site.help.glossary.aCustomImageDisplayed": "Własny obrazek wyświetlany na komórce zamiast domyślnego koloru. Skiny mogą być flagami krajów, memami, logo albo własnymi grafikami. W Agar.io większość skinów jest płatna. W Expanding Land skiny są <strong>darmowe</strong> dzięki modom takim jak Legend Mod.",
"site.help.glossary.clan": "<span class=\"emoji\">🏰</span> Klan",
"site.help.glossary.aGroupOfPlayers": "Grupa graczy, którzy grają razem i zwykle mają wspólny tag w nicku (np. [LC] dla <a href=\"https://join.lc\" style=\"color:#6ee7b7\">Legend Clan</a>). Klany często mają własne serwery Discord, treningi i wewnętrzne rankingi.",
"site.help.glossary.privateServer": "<span class=\"emoji\">🖥️</span> Serwer prywatny",
"site.help.glossary.aGameServerRun": "Serwer gry działający niezależnie od oficjalnych serwerów Agar.io. Serwery prywatne mogą mieć własne zasady, wyższe limity graczy i inne funkcje. <a href=\"https://expanding.land/\" style=\"color:#6ee7b7\">Expanding Land</a> to serwer prywatny napisany od zera w C, obsługujący do 3840 graczy na arenę.",
"site.help.glossary.expandingLandTerms": "🌍 Pojęcia z Expanding Land",
"site.help.glossary.dynamicMap": "<span class=\"emoji\">🗺️</span> Dynamiczna mapa",
"site.help.glossary.expandingLandSMap": "Mapa Expanding Land sama zmienia rozmiar w zależności od liczby aktywnych graczy. Więcej graczy = większa mapa. Mniej graczy = mniejsza mapa. Mapa ma od ¼× do 4× standardowego rozmiaru, więc gęstość graczy jest stała bez względu na to, ile osób jest online.",
"site.help.glossary.dangerZone": "<span class=\"emoji\">⚠️</span> Strefa zagrożenia",
"site.help.glossary.whenTheExpandingLand": "Gdy mapa Expanding Land się kurczy, zewnętrzny pierścień staje się „strefą zagrożenia”. Gracze, którzy mają komórki w tym obszarze, dostają podbicie mnożnika anti-team (+0.01 na cykl ubytku). Strefa zagrożenia zachęca graczy do ruchu w stronę środka, gdy mapa się zmniejsza, i zapobiega kampieniu przy krawędziach.",
"site.help.glossary.sessionStats": "<span class=\"emoji\">📊</span> Statystyki sesji",
"site.help.glossary.afterDyingInExpanding": "Po śmierci w Expanding Land widzisz statystyki swojej sesji: czas przeżycia, największą osiągniętą masę, zjedzone jedzenie i zjedzonych graczy. Te statystyki pomagają śledzić postępy i porównywać wyniki między sesjami.",
"site.help.glossary.coordinateScrambling": "<span class=\"emoji\">🔒</span> Mieszanie współrzędnych",
"site.help.glossary.anAntiCheatFeature": "Funkcja anti-cheat w Expanding Land, w której serwer wysyła każdemu graczowi inne przesunięcie współrzędnych. Przez to programy do oszukiwania nie mogą odczytać dokładnych pozycji innych graczy z pakietów sieciowych: widok każdego gracza jest zakodowany inaczej.",
"site.help.glossary.wssTls": "<span class=\"emoji\">🔐</span> WSS / TLS",
"site.help.glossary.encryptedWebsocketConnectionsUsed": "Szyfrowane połączenia WebSocket używane przez Expanding Land. Wszystkie dane między twoją przeglądarką a serwerem gry są szyfrowane przez TLS (tę samą technologię, która chroni bankowość internetową). To zapobiega podsłuchiwaniu pakietów i atakom man-in-the-middle.",
"site.help.glossary.playExpandingLandFree": "🎮 Graj w Expanding Land za darmo",
"site.help.glossary.bestIoGames2026": "Najlepsze gry IO 2026",
"site.help.glossary.elVsAgarIo": "EL vs Agar.io",
"site.help.glossary.playersAndBots": "Gracze i boty"
}]);
if (window.LMi18n && window.LMi18n._drain) window.LMi18n._drain();
